'use strict';
(()=>{
const el=id=>document.getElementById(id),months=['Januar','Februar','Mars','April','Mai','Juni','Juli','August','September','Oktober','November','Desember'];
const years=[...new Set(window.RAIN_DATA.map(r=>Number(r.month.slice(0,4))))].sort((a,b)=>b-a),latest=years[0];
const model=window.RainModel.createModel(window.RAIN_DATA);let expanded=false;
const number=n=>n===null?'—':n.toLocaleString('nb-NO',{minimumFractionDigits:1,maximumFractionDigits:1});
const signed=n=>n===null?'—':(n>=0?'+':'−')+number(Math.abs(n));
const period=r=>r.month?months[r.month-1]:r.count===12?'Hele året':r.count?'Januar–'+months[r.availableMonths.at(-1)-1].toLowerCase():'Ingen data';
function chart(r){const W=900,H=275,L=55,R=15,T=20,B=40,h=H-T-B,step=(W-L-R)/12,max=Math.ceil(Math.max(...r.months.map(m=>Math.max(m.actual??0,m.normal)))/100)*100,y=v=>T+h-v/max*h;
let s=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Månedsnedbør i ${r.year} og normal 1991–2020"><title>Månedsnedbør ${r.year}. Manglende måneder vises uten observert stolpe.</title>`;
for(let i=0;i<=4;i++){const v=max*i/4;s+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e2ebed"/><text x="${L-10}" y="${y(v)+4}" text-anchor="end" fill="#657a83" font-size="12">${Math.round(v)}</text>`}
r.months.forEach((m,i)=>{const x=L+i*step,dim=r.month&&r.month!==m.month?.3:1;s+=`<g opacity="${dim}"><rect x="${x+step*.53}" y="${y(m.normal)}" width="${step*.27}" height="${H-B-y(m.normal)}" fill="#d5e0e3" rx="2"><title>${months[i]} normal: ${number(m.normal)} mm</title></rect>`;if(m.actual!==null)s+=`<rect x="${x+step*.18}" y="${y(m.actual)}" width="${step*.27}" height="${H-B-y(m.actual)}" fill="#138b80" rx="2"><title>${months[i]} ${r.year}: ${number(m.actual)} mm</title></rect>`;else s+=`<text x="${x+step*.3}" y="${H-B-7}" text-anchor="middle" font-size="12" fill="#758992">–</text>`;s+=`<text x="${x+step*.48}" y="${H-15}" text-anchor="middle" font-size="12" fill="#657a83">${months[i].slice(0,3)}</text></g>`});el('annualChart').innerHTML=s+'</svg>';
}
function render(){const year=+el('annualYear').value,month=+el('annualMonth').value,r=model.annual(year,month),ytd=model.annual(latest);el('annualYtd').textContent=`${latest} til og med ${months[ytd.availableMonths.at(-1)-1].toLowerCase()}: ${number(ytd.actual)} mm · ${number(Math.abs(ytd.percent))} % ${ytd.percent>=0?'over':'under'} normalen for samme periode.`;
el('annualActual').textContent=number(r.actual)+' mm';el('annualNormal').textContent=number(r.normal)+' mm';el('annualDeviation').textContent=r.percent===null?'Mangler data':number(Math.abs(r.percent))+' % '+(r.percent>=0?'over':'under');el('annualDifference').textContent=r.actual===null?'Måneden er ikke tilgjengelig':signed(r.difference)+' mm mot normalen';el('annualPeriod').textContent=period(r)+' '+year;el('annualNormalPeriod').textContent=period(r)+' · normal 1991–2020';el('annualDeviation').className=r.percent>=0?'positive':'negative';el('annualChartTitle').textContent='Måned for måned · '+year;chart(r);
el('annualMonthRows').innerHTML=r.months.map(m=>`<tr${month===m.month?' class="selected-month"':''}><td><button data-month="${m.month}">${months[m.month-1]}</button></td><td>${number(m.actual)}${m.actual===null?'':' mm'}</td><td>${number(m.normal)} mm</td><td class="${m.actual>=m.normal?'positive':'negative'}">${m.actual===null?'Ikke tilgjengelig':signed(m.actual-m.normal)+' mm'}</td><td>${m.actual===null?'—':signed(100*(m.actual/m.normal-1))+' %'}</td></tr>`).join('');el('annualMonthRows').querySelectorAll('button').forEach(b=>b.onclick=()=>{el('annualMonth').value=b.dataset.month;render()});
el('annualTableTitle').textContent=month?months[month-1]+' gjennom alle år':'Samlet nedbør per år';const list=expanded?years:years.slice(0,12);el('annualYearRows').innerHTML=list.map(y=>{const a=model.annual(y,month);return `<tr${y===year?' class="selected-month"':''}><td><button data-year="${y}">${y}</button>${y<1896?' <span class="small muted">Foreløpig</span>':''}</td><td>${number(a.actual)}${a.actual===null?'':' mm'}</td><td>${number(a.normal)}${a.normal===null?'':' mm'}</td><td class="${a.percent>=0?'positive':'negative'}">${a.percent===null?'—':signed(a.percent)+' %'}</td><td>${a.count?period(a):'Ikke tilgjengelig'}${!a.complete&&a.count?' · ufullstendig år':''}</td></tr>`}).join('');el('annualYearRows').querySelectorAll('button').forEach(b=>b.onclick=()=>{el('annualYear').value=b.dataset.year;render();el('annual').scrollIntoView({behavior:'smooth'})});el('annualAllYears').textContent=expanded?'Vis de 12 nyeste årene':'Vis alle '+years.length+' år';
}
years.forEach(y=>el('annualYear').add(new Option(y,y)));months.forEach((m,i)=>el('annualMonth').add(new Option(m,i+1)));el('annualYear').value=latest;el('annualYear').onchange=render;el('annualMonth').onchange=render;el('annualAllYears').onclick=()=>{expanded=!expanded;render()};render();
})();
